418	export function questionUser(prompt: string, turns: Turn[], l: Ledger, target: TrackKey, blocked: TrackKey | null): string {
419	  return JSON.stringify({
420	    prompt,
421	    answered: turns.filter((t) => t.answer).map((t) => ({ track: t.track, question: t.question, answer: decisionOf(t) })),
422	    ambiguity_now: l,
423	    suggested_track: target,
424	    blocked_track: blocked,
425	  });
426	}
