464	const LABEL = /^(이게 뭐냐면|비유하자면|조금 더 자세히|그래서 왜 재밌냐면)\s*[:：]\s*/;
465	export function parseConcept(raw: unknown, fallback: Concept): Concept {
466	  const r = (raw ?? {}) as Record<string, unknown>;
467	  const str = (v: unknown, max = 300) => (typeof v === 'string' ? v.trim().replace(LABEL, '').slice(0, max) : '');
468	  const details = Array.isArray(r.details) ? r.details.map((d) => str(d, 200)).filter(Boolean).slice(0, 8) : [];
469	  return {
470	    title: str(r.title, 40) || fallback.title,
471	    one_liner: str(r.one_liner) || fallback.one_liner,
472	    what: str(r.what) || fallback.what,
473	    analogy: str(r.analogy) || fallback.analogy,
474	    details: details.length ? details : fallback.details,
475	    so_what: str(r.so_what) || fallback.so_what,
476	  };
477	}
