142	  }, [turn.idx, enter]);
143	
144	  function toggle(o: string) {
145	    setEmpty(false);
146	    if (!turn.multi) return setChoices([o]);
147	    setChoices((c) => (c.includes(o) ? c.filter((x) => x !== o) : o === RECOMMEND ? [o] : [...c.filter((x) => x !== RECOMMEND), o]));
