189	                onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); submit(); } }}
190	                aria-describedby={`h-${turn.id}${empty ? ` e-${turn.id}` : ''}`} aria-invalid={empty || undefined}
191	              />
