62	export function listSessions(limit = 20) {
63	  ensureSchema();
64	  return db().prepare(`
65	    SELECT s.id, s.prompt, s.status, s.created_at, r.title, (SELECT COUNT(*) FROM step1_turns t WHERE t.session_id = s.id AND t.answer IS NOT NULL) AS answered
66	    FROM step1_sessions s LEFT JOIN step1_results r ON r.session_id = s.id ORDER BY s.created_at DESC LIMIT ?`).all(limit) as
67	    { id: string; prompt: string; status: string; created_at: string; title: string | null; answered: number }[];
68	}
