50	/** 을/를, 이/가 … picked by the last syllable's final consonant. */
51	export function josa(word: string, withFinal: string, without: string): string {
52	  const c = word.replace(/[\s'"’”)\].,!?…]+$/, '').slice(-1).charCodeAt(0);
53	  if (c >= 0xac00 && c <= 0xd7a3) return (c - 0xac00) % 28 ? withFinal : without;
54	  return without;
55	}
