57	const byPosition = (prompt: string, words: string[]) => words.filter((w) => prompt.includes(w)).sort((a, b) => prompt.indexOf(a) - prompt.indexOf(b));
58	
59	/** Characters and places in prompt order. `player` is a character written as the subject of something it does
60	 *  ("고양이가 운영하는"), not one that merely shows up ("좀비가 나오는"), so enemies are never offered as the player. */
61	export function themes(prompt: string): { chars: string[]; places: string[]; player: string | null } {
62	  const chars = byPosition(prompt, CHARACTERS);
63	  const player = chars.find((c) => new RegExp(`${c}(?:이|가|은|는)(?!\\s*(?:나오|나타|등장|쫓아|몰려|습격|공격|덮치))`).test(prompt)) ?? null;
64	  return { chars: chars.slice(0, 1), places: byPosition(prompt, PLACES).slice(0, 2), player };
65	}
66	
67	function subject(prompt: string): string {
68	  const { chars, places } = themes(prompt);
69	  const words = [...chars, ...places].slice(0, 2);
70	  if (!words.length) return '이 게임';
71	  if (words.length === 1) return `${words[0]}${josa(words[0], '이', '가')} 나오는 이 게임`;
72	  return `${words[0]}${josa(words[0], '과', '와')} ${words[1]}${josa(words[1], '이', '가')} 나오는 이 게임`;
73	}
