75	export function initialLedger(prompt: string): Ledger {
76	  const l = {} as Ledger;
77	  for (const k of TRACK_KEYS) l[k] = SIGNALS[k].test(prompt) ? 0.55 : 1;
78	  if (themes(prompt).player) l.role = Math.min(l.role, 0.7);
79	  return l;
80	}
