86	/** Deterministic re-score after an answer: the answered track drops by how concrete the answer was, and every further
87	 *  answer on it drops it at least 0.15 more. Words the player typed (not the preset option labels) lower other tracks a little. */
88	export function applyAnswer(l: Ledger, track: TrackKey, a: Answer): Ledger {
89	  const next = { ...l };
90	  const picked = a.recommended ? [] : a.choices.filter((c) => c !== RECOMMEND);
91	  const text = a.text.trim();
92	  let score: number;
93	  if (picked.length && text) score = 0.05;
94	  else if (picked.length) score = 0.15;
95	  else if (text.length >= 6) score = 0.1;
96	  else if (a.recommended || a.choices.includes(RECOMMEND)) score = 0.3;
97	  else score = 0.45; // a very short free answer stays fuzzy
98	  next[track] = clamp(Math.min(l[track] - 0.15, score));
99	  for (const k of TRACK_KEYS) if (k !== track && SIGNALS[k].test(text)) next[k] = Math.min(next[k], 0.5);
100	  return next;
101	}
