103	export const blockedTrack = (history: TrackKey[]): TrackKey | null =>
104	  history.length >= 2 && history.at(-1) === history.at(-2) ? history.at(-1)! : null;
105	
106	/** Most ambiguous track; ties go to the track asked fewer times, then the heavier one.
107	 *  After 2 consecutive turns on one track, zoom out to another (ouroboros breadth control).
108	 *  The first question is the ontological one ("what IS this game?") unless the prompt already pinned the fun down. */
109	export function pickTrack(l: Ledger, history: TrackKey[]): TrackKey {
110	  if (!history.length && l.fun > CLEAR) return 'fun';
111	  const blocked = blockedTrack(history);
112	  const asks = (k: TrackKey) => history.filter((h) => h === k).length;
113	  return TRACKS.filter((t) => t.key !== blocked)
114	    .sort((a, b) => l[b.key] - l[a.key] || asks(a.key) - asks(b.key) || b.weight - a.weight)[0].key;
115	}
