117	/** Tracks a one-page concept cannot do without: an early stop waits until these are clear too (ouroboros closure). */
118	export const CORE: TrackKey[] = ['fun', 'loop', 'win'];
119	
120	export function shouldStop(l: Ledger, asked: number): boolean {
121	  return asked >= MAX_QUESTIONS || (overall(l) <= THRESHOLD && CORE.every((k) => l[k] <= CLEAR));
122	}
