124	/** Stored form of an answer: RECOMMEND becomes the first option (always the recommended one), flagged so it shows as "(추천)". */
125	export function resolveAnswer(a: Answer, options: string[]): Answer {
126	  return a.choices.includes(RECOMMEND) && options[0] ? { choices: [options[0]], text: a.text, recommended: true } : a;
127	}
