129	/** One readable decision per answered turn ("추천" picks the first option, which is always the recommended one). */
130	export function decisionOf(t: Turn): string {
131	  if (!t.answer) return '';
132	  const rec = (c: string) => `${c}(추천)`;
133	  const parts = t.answer.recommended ? t.answer.choices.map(rec) : t.answer.choices.map((c) => (c === RECOMMEND ? rec(t.options[0] ?? '추천안') : c));
134	  if (t.answer.text.trim()) parts.push(t.answer.text.trim());
135	  return parts.join(', ');
136	}
