138	export function decisions(turns: Turn[]): Decision[] {
139	  const out: Decision[] = [];
140	  for (const k of TRACK_KEYS) {
141	    const d = turns.filter((t) => t.track === k && t.answer).map(decisionOf).filter(Boolean);
142	    if (d.length) out.push({ key: k, track: label(k), decision: d.join(', ') });
143	  }
144	  return out;
145	}
