339	/** Restate gate goal line, and the mock concept for the result screen (ELI5: what, analogy, details, so what). */
340	export function goalLine(prompt: string, turns: Turn[]): string {
341	  const role = said(turns, 'role').replace(/\(.*?\)/g, '').trim();
342	  const loop = said(turns, 'loop');
343	  if (role && loop) return `${role}${josa(role, '이', '가')} 되어 ${loop}${josa(loop, '을', '를')} 반복하는 게임이에요.`;
344	  if (loop) return `${loop}${josa(loop, '을', '를')} 반복하는 게임이에요.`;
345	  return `${quoted(short(prompt, 60), '을', '를')} 바탕으로 한 게임이에요.`;
346	}
