359	export function mockConcept(prompt: string, turns: Turn[]): Concept {
360	  const k = gameKind(prompt, turns);
361	  const { chars, places } = themes(prompt);
362	  const head = [...places.slice(0, 1), ...chars].join(' ') || '나만의';
363	  const fun = said(turns, 'fun');
364	  const loop = said(turns, 'loop');
365	  const audience = said(turns, 'audience');
366	  const platform = said(turns, 'platform');
367	  const unique = said(turns, 'unique');
368	  const role = said(turns, 'role');
369	  const loops = picks(turns, 'loop');
370	  const win = said(turns, 'win');
371	  const moods = picks(turns, 'mood');
372	  // "조금 더 자세히": how a session plays out, not the decisions table again.
373	  const details = [
374	    role && loops[0] && `처음 켜면 ‘${role}’ 입장에서 바로 ‘${loops[0]}’부터 해요.`,
375	    loops.length > 1 ? `한 바퀴(계속 반복하는 흐름)는 ${loops.slice(0, 4).join(' → ')} → 다시 처음이에요.` : loops[0] && `한 바퀴(계속 반복하는 흐름)는 ‘${loops[0]}’ 하나로 단순하게 가요.`,
376	    win && (/끝이 없/.test(win) ? '정해진 끝 없이 계속 이어지고, 그만큼 내 공간이 자라요.' : `한 판은 ‘${win}’ 규칙으로 끝나요.`),
377	    platform && `‘${platform}’에 맞춰 한 판 길이와 조작을 짜요.`,
378	    moods.length > 0 && `화면과 소리는 ${moods.slice(0, 3).map((m) => `‘${m}’`).join(', ')} 쪽으로 맞춰요.`,
379	  ].filter((d): d is string => !!d);
380	  return {
381	    title: `${head} ${TITLE_TAIL[k]}`,
382	    one_liner: goalLine(prompt, turns),
383	    what: fun && loop ? `한마디로 ${fun}${josa(fun, '으로', '로')} ${loop}${josa(loop, '을', '를')} 계속하는 게임이에요.` : `한마디로 ${quoted(short(prompt, 40), '을', '를')} 직접 해 보는 게임이에요.`,
