428	const str = (v: unknown, max = 300) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
429	const PREAMBLE = /^(좋은|좋아요|좋네요|좋습니다|멋진|멋져요|훌륭|알겠|그렇군요|그렇구나|네[,.! ]|오[,.!~ ]|와[,.!~ ]|감사|재밌|흥미)/;
430	
431	/** ouroboros question rules: one question (one "?", at the end), 1-2 sentences, no preamble. */
432	export function isOneQuestion(q: string): boolean {
433	  const marks = q.match(/[?？]/g)?.length ?? 0;
434	  const sentences = q.split(/(?<=[.!?？。])\s+/).filter(Boolean).length;
435	  return marks === 1 && /[?？]$/.test(q) && sentences <= 2 && !/[!！]/.test(q) && !PREAMBLE.test(q);
436	}
437	
438	/** Validate model output; null means "use the mock instead". */
439	export function parseQuestion(raw: unknown, blocked: TrackKey | null): { q: Question | null; ledger: Partial<Ledger>; done: boolean } {
440	  const r = (raw ?? {}) as Record<string, unknown>;
441	  const ledger: Partial<Ledger> = {};
442	  const amb = (r.ambiguity ?? {}) as Record<string, unknown>;
443	  for (const k of TRACK_KEYS) if (typeof amb[k] === 'number' && Number.isFinite(amb[k])) ledger[k] = clamp(amb[k] as number);
444	  const done = r.done === true;
445	  const track = r.track as TrackKey;
446	  const question = str(r.question);
447	  const options = Array.isArray(r.options) ? [...new Set(r.options.map((o) => str(o, 80)).filter((o) => o && o !== RECOMMEND))].slice(0, 5) : [];
448	  const ok = TRACK_KEYS.includes(track) && track !== blocked && isOneQuestion(question) && options.length >= 3;
449	  return { q: ok ? { track, question, hint: str(r.hint, 200), options, multi: r.multi === true, allow_free: r.allow_free !== false } : null, ledger, done };
450	}
