 12	function Inline({ line }: { line: string }) {
 13	  return parseInline(line).map((t, i) =>
 14	    t.t === 'text' ? <Fragment key={i}>{t.v}</Fragment>
 15	    : t.t === 'bold' ? <strong key={i}>{t.v}</strong>
 16	    : t.t === 'link' ? <a key={i} href={t.href} target="_blank" rel="noopener noreferrer">{t.v}</a>
 17	    : <a key={i} className="url" href={t.href} target="_blank" rel="noopener noreferrer">{t.href}</a>,
 18	  );
 19	}
 20	
 21	function Rich({ text }: { text: string }) {
 22	  return parseBlocks(text).map((b, i) =>
 23	    b.t === 'p' ? (
 24	      <p key={i}>{b.lines.map((l, k) => <Fragment key={k}>{k > 0 && <br />}<Inline line={l} /></Fragment>)}</p>
 25	    ) : b.t === 'ul' ? (
 26	      <ul key={i}>{b.items.map((it, k) => <li key={k}><Inline line={it} /></li>)}</ul>
 27	    ) : (
 28	      <ol key={i}>{b.items.map((it, k) => <li key={k}><Inline line={it} /></li>)}</ol>
 29	    ),
 30	  );
 31	}
