 39	        <div className="msg__body"><Rich text={m.content} /></div>
 40	      </li>
 41	    );
 42	  }
 43	  const urls = extractUrls(m.content);
 44	  return (
 45	    <li className="msg msg--agent">
 46	      <p className="msg__who"><Icon name="agent" />{agentName}{stamp}</p>
 47	      <div className="msg__body"><Rich text={m.content} /></div>
 48	      {urls.length > 0 && <Gallery urls={urls} />}
 49	    </li>
 50	  );
 51	}
