 53	export default function Chat({ card, messages }: { card: Card; messages: Message[] }) {
 54	  const { send } = useActions();
 55	  const [text, setText] = useState('');
 56	  const [pending, setPending] = useState(false);
 57	  const [err, setErr] = useState<string | null>(null);
 58	  const [note, setNote] = useState<string | null>(null);
 59	  const listRef = useRef<HTMLOListElement>(null);
 60	  const inputId = `msg-${card.id}`;
 61	  const agentName = `${card.title} 에이전트`;
 62	
 63	  useEffect(() => {
 64	    const el = listRef.current;
 65	    if (el) el.scrollTop = el.scrollHeight;
 66	  }, [messages.length, pending]);
 67	
 68	  async function submit() {
 69	    const content = text.trim();
 70	    if (!content || pending) return;
 71	    setPending(true);
 72	    setErr(null);
 73	    try {
 74	      const r = await send(card.id, content);
 75	      setText('');
 76	      setNote(r.error ? 'LLM 응답을 받지 못해 기본 답변을 보여 드려요.' : null);
 77	    } catch (e) {
 78	      setErr((e as Error).message);
 79	    } finally {
 80	      setPending(false);
 81	    }
 82	  }
 83	
 84	  return (
 85	    <>
 86	      {card.status === 'frozen' && (
 87	        <div className="notice node__verdict">
 88	          <Icon name="lock" />
 89	          <div><p className="node__verdict-label">결정</p><p>{card.decision ?? '결정 내용이 없어요.'}</p></div>
 90	        </div>
 91	      )}
 92	      <ol className="chat node__chat nowheel" ref={listRef} aria-label={`${card.title} 대화`} aria-busy={pending}>
 93	        {messages.length === 0 && <li className="meta">아직 대화가 없어요. 이 카드에서 정할 것을 물어보세요.</li>}
 94	        {messages.map((m) => <Msg key={m.id} m={m} agentName={agentName} />)}
 95	        {pending && (
 96	          <li className="msg msg--agent">
 97	            <p className="msg__who"><Icon name="agent" />{agentName}<span className="visually-hidden">답변을 쓰는 중</span></p>
 98	            <span className="skeleton node__skel" /><span className="skeleton node__skel" />
 99	          </li>
100	        )}
101	      </ol>
102	      {card.status === 'active' ? (
103	        <form className="composer" onSubmit={(e) => { e.preventDefault(); submit(); }}>
104	          <label className="visually-hidden" htmlFor={inputId}>메시지</label>
105	          <textarea
106	            className="textarea" id={inputId} name="message" rows={1} maxLength={4000} value={text} disabled={pending}
107	            placeholder="예: 비밀방 아이디어를 더 주세요" onChange={(e) => setText(e.target.value)}
108	            onKeyDown={(e) => {
109	              if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
110	                e.preventDefault();
111	                submit();
112	              }
113	            }}
114	          />
115	          <button type="submit" className="btn" disabled={pending || !text.trim()} aria-busy={pending}>보내기</button>
116	        </form>
117	      ) : (
118	        <p className="meta">
119	          {card.status === 'frozen' ? '동결된 카드는 읽기만 할 수 있어요. 고치려면 되돌리기를 눌러요.' : '취소된 카드예요. 되돌리기를 누르면 다시 대화할 수 있어요.'}
120	        </p>
121	      )}
122	      {err && <div className="notice notice--error" role="alert"><Icon name="alert" /><p>{err}</p></div>}
123	      {note && <p className="meta" role="status">{note}</p>}
124	    </>
125	  );
