  9	// One request per URL per page load, shared by every gallery that shows it.
 10	const cache = new Map<string, Promise<Preview>>();
 11	function loadPreview(url: string): Promise<Preview> {
 12	  let p = cache.get(url);
 13	  if (!p) {
 14	    const failed: Preview = { url, kind: 'page', title: null, description: null, image: null, site: hostOf(url), error: 'failed' };
 15	    p = fetch(`/api/preview?url=${encodeURIComponent(url)}`)
 16	      .then((r) => (r.ok ? (r.json() as Promise<Preview>) : failed))
 17	      .catch(() => failed);
 18	    cache.set(url, p);
 19	  }
 20	  return p;
 21	}
