 82	export default function Gallery({ urls }: { urls: string[] }) {
 83	  const [view, setView] = useState<'slide' | 'grid'>('slide');
 84	  const [pos, setPos] = useState(0);
 85	  const [box, setBox] = useState<{ src: string; alt: string } | null>(null);
 86	  const track = useRef<HTMLUListElement>(null);
 87	  const dialog = useRef<HTMLDialogElement>(null);
 88	  const opener = useRef<HTMLElement | null>(null);
 89	  const closeBtn = useRef<HTMLButtonElement>(null);
 90	
 91	  useEffect(() => {
 92	    if (!box) return;
 93	    dialog.current?.showModal();
 94	    closeBtn.current?.focus();
 95	  }, [box]);
 96	
 97	  const stride = () => {
 98	    const el = track.current;
 99	    const first = el?.firstElementChild as HTMLElement | null;
100	    return el && first ? first.offsetWidth + parseFloat(getComputedStyle(el).columnGap || '0') : 1;
101	  };
102	  const go = (dir: 1 | -1) => track.current?.scrollBy({ left: dir * stride(), behavior: reduceMotion() ? 'auto' : 'smooth' });
103	  const onScroll = () => {
104	    const el = track.current;
105	    if (!el) return;
106	    const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 2;
107	    setPos(atEnd ? urls.length - 1 : Math.round(el.scrollLeft / stride()));
108	  };
109	  const open: Open = (src, alt, from) => {
110	    opener.current = from;
111	    setBox({ src, alt });
112	  };
113	
114	  return (
115	    <section className="gallery nowheel" aria-label="링크 미리보기">
116	      <div className="gallery__bar">
117	        <p className="meta num">미리보기 {urls.length}개</p>
118	        {urls.length > 1 && (
119	          <div className="seg" role="group" aria-label="보기 방식">
120	            <button type="button" aria-pressed={view === 'slide'} onClick={() => setView('slide')}>슬라이드</button>
121	            <button type="button" aria-pressed={view === 'grid'} onClick={() => { setView('grid'); setPos(0); }}>격자</button>
122	          </div>
123	        )}
124	      </div>
125	      <ul className="gallery__track" data-view={urls.length > 1 ? view : 'grid1'} ref={track} onScroll={view === 'slide' ? onScroll : undefined}>
126	        {urls.map((u, i) => (isImageUrl(u) ? <ImageTile key={u} url={u} onOpen={open} eager={i === 0} /> : <PageTile key={u} url={u} eager={i === 0} />))}
127	      </ul>
128	      {urls.length > 1 && view === 'slide' && (
129	        <div className="gallery__nav">
130	          <button type="button" className="btn btn--ghost btn--icon btn--sm" aria-label="이전 미리보기" onClick={() => go(-1)} disabled={pos === 0}><Icon name="prev" /></button>
131	          <p className="meta num" aria-live="polite">{pos + 1} / {urls.length}</p>
132	          <button type="button" className="btn btn--ghost btn--icon btn--sm" aria-label="다음 미리보기" onClick={() => go(1)} disabled={pos >= urls.length - 1}><Icon name="next" /></button>
133	        </div>
134	      )}
135	      {box && createPortal(
136	        <dialog
137	          ref={dialog} className="lightbox" aria-label={box.alt}
138	          onClose={() => { setBox(null); opener.current?.focus(); }}
139	          onClick={(e) => e.target === e.currentTarget && dialog.current?.close()}
140	        >
141	          <img src={box.src} alt={box.alt} />
142	          <div className="lightbox__bar">
143	            <a className="url meta" href={box.src} target="_blank" rel="noopener noreferrer">{box.src}</a>
144	            <form method="dialog"><button type="submit" className="btn btn--sm" ref={closeBtn}>닫기</button></form>
145	          </div>
146	        </dialog>,
147	        document.body,
148	      )}
149	    </section>
150	  );
151	}

