    28	/** BEGIN/COMMIT around fn; node:sqlite has no transaction helper. */
    29	function tx<T>(fn: () => T): T {
    30	  const d = db();
    31	  d.exec('BEGIN IMMEDIATE');
    32	  try {
    33	    const r = fn();
    34	    d.exec('COMMIT');
    35	    return r;
    36	  } catch (e) {
    37	    d.exec('ROLLBACK');
    38	    throw e;
    39	  }
    40	}
