   150	/** Create (once per session) a workflow from step1's tables. */
   151	export function importStep1(sessionId: string): { id: string } | { error: string } {
   152	  const source = `step1:${sessionId}`;
   153	  const d = wf();
   154	  const existing = d.prepare('SELECT id FROM wf_workflows WHERE source = ?').get(source);
   155	  if (existing) return { id: String(existing.id) };
   156	  if (!tableExists('step1_sessions') || !tableExists('step1_turns')) {
   157	    return { error: '질문하기 기록이 아직 없어요. 질문하기에서 먼저 답변을 끝내 주세요.' };
   158	  }
   159	  const session = d.prepare('SELECT * FROM step1_sessions WHERE id = ?').get(sessionId);
   160	  if (!session) return { error: '그 질문하기 기록을 찾지 못했어요. 예시 워크플로우를 보여 드려요.' };
   161	  const turns = d.prepare('SELECT * FROM step1_turns WHERE session_id = ? AND answer IS NOT NULL ORDER BY idx').all(sessionId);
   162	  // Import only finished sessions: the workflow is created once per source, so a partial import would stick forever.
   163	  if (session.status !== 'done' || turns.length === 0) {
