   165	  }
   166	  const result = tableExists('step1_results') ? d.prepare('SELECT * FROM step1_results WHERE session_id = ?').get(sessionId) : undefined;
   167	
   168	  let concept: { what?: string; analogy?: string; details?: string[]; so_what?: string } = {};
   169	  try {
   170	    concept = result ? JSON.parse(String(result.concept)) : {};
   171	  } catch {
   172	    /* keep empty; the one-liner still carries the concept */
   173	  }
