     3	const URL_RE = /https?:\/\/[A-Za-z0-9\-._~:/?#@!$&*+,;=%()]+/g;
     4	const IMAGE_EXT = /\.(png|jpe?g|gif|webp|avif|svg)$/i;
     5	const IMAGE_HOSTS = new Set(['picsum.photos', 'images.unsplash.com']);
     6	
     7	/** Trim sentence punctuation and an unbalanced closing paren (markdown `[t](url)`, "(see https://x)"). */
     8	export function trimUrl(raw: string): string {
     9	  let u = raw.replace(/[.,;:!?*]+$/, '');
    10	  while (u.endsWith(')') && (u.match(/\(/g)?.length ?? 0) < (u.match(/\)/g)?.length ?? 0)) {
    11	    u = u.slice(0, -1).replace(/[.,;:!?*]+$/, '');
    12	  }
    13	  return u;
    14	}
    15	
    16	/** Every distinct http(s) URL in the text, in order of appearance. */
    17	export function extractUrls(text: string): string[] {
    18	  const out: string[] = [];
    19	  for (const m of text.matchAll(URL_RE)) {
    20	    const u = trimUrl(m[0]);
    21	    if (!isHttpUrl(u) || out.includes(u)) continue;
    22	    out.push(u);
    23	  }
    24	  return out;
    25	}
    26	
    27	export function isHttpUrl(s: string): boolean {
    28	  try {
    29	    const u = new URL(s);
    30	    return (u.protocol === 'http:' || u.protocol === 'https:') && !!u.hostname;
    31	  } catch {
    32	    return false;
    33	  }
    34	}
    35	
    36	/** Image by file extension or by a known image host; such URLs render as <img> and are never fetched server-side. */
    37	export function isImageUrl(s: string): boolean {
    38	  try {
    39	    const u = new URL(s);
    40	    return IMAGE_EXT.test(u.pathname) || IMAGE_HOSTS.has(u.hostname);
    41	  } catch {
    42	    return false;
    43	  }
    44	}
    45	
    46	export function hostOf(s: string): string {
    47	  try {
    48	    return new URL(s).hostname.replace(/^www\./, '');
    49	  } catch {
    50	    return s;
    51	  }
    52	}
